import { defineComponent, computed, h, ref, type PropType } from 'vue';
import { checkboxStyleKeys, getCheckboxState, getNextCheckboxState } from '../lib/core';
import type { CheckboxCheckedState } from '../lib/core';
import styles from './checkbox.module.scss';

export const Checkbox = defineComponent({
	name: 'Checkbox',
	props: {
		modelValue: {
			type: [Boolean, String] as PropType<boolean | 'indeterminate'>,
			default: undefined,
		},
		defaultChecked: {
			type: [Boolean, String] as PropType<boolean | 'indeterminate'>,
			default: false,
		},
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit }) {
		const internalChecked = ref<CheckboxCheckedState>(props.defaultChecked);
		const isChecked = computed<CheckboxCheckedState>(() =>
			props.modelValue !== undefined ? (props.modelValue === 'indeterminate' ? 'indeterminate' : !!props.modelValue) : internalChecked.value,
		);
		const state = computed(() => getCheckboxState(isChecked.value));
		const ariaChecked = computed(() => (state.value === 'checked' ? 'true' : state.value === 'mixed' ? 'mixed' : 'false'));

		function handleClick() {
			const next = getNextCheckboxState(isChecked.value);
			if (props.modelValue === undefined) {
				internalChecked.value = next;
			}
			emit('update:modelValue', next);
			emit('change', next);
		}

		return () =>
			h(
				'button',
				{
					type: 'button',
					role: 'checkbox',
					'aria-checked': ariaChecked.value,
					'data-state': state.value,
					disabled: props.disabled,
					class: styles[checkboxStyleKeys.root],
					onClick: handleClick,
				},
				[
					h('span', { class: styles[checkboxStyleKeys.indicator] }, [
						state.value === 'checked'
							? h(
									'svg',
									{
										xmlns: 'http://www.w3.org/2000/svg',
										viewBox: '0 0 24 24',
										fill: 'none',
										stroke: 'currentColor',
										'stroke-width': '3',
										'stroke-linecap': 'round',
										'stroke-linejoin': 'round',
									},
									[h('path', { d: 'M20 6 9 17l-5-5' })],
								)
							: null,
						state.value === 'mixed'
							? h(
									'svg',
									{
										xmlns: 'http://www.w3.org/2000/svg',
										viewBox: '0 0 24 24',
										fill: 'none',
										stroke: 'currentColor',
										'stroke-width': '3',
										'stroke-linecap': 'round',
									},
									[h('path', { d: 'M5 12h14' })],
								)
							: null,
					]),
				],
			);
	},
});

export default Checkbox;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	width: var(--tile-checkbox-size, 1rem);
	height: var(--tile-checkbox-size, 1rem);
	border-radius: var(--tile-checkbox-radius, #{$radius-sm});
	border: var(--tile-checkbox-border-width, 1px) solid var(--tile-checkbox-border, #{$input});
	background-color: var(--tile-checkbox-background, initial);
	box-shadow: var(--tile-checkbox-shadow, #{$shadow-sm});
	transition:
		background-color $transition-fast,
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: var(--tile-checkbox-focus-border, #{$ring});
		box-shadow: var(--tile-checkbox-focus-shadow, 0 0 0 1px #{$ring});
		outline: none;
	}

	&:disabled {
		cursor: not-allowed;
		opacity: 0.5;
	}

	&[aria-invalid='true'] {
		border-color: $destructive;
		box-shadow: var(--tile-checkbox-error-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-checkbox-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}

	&[data-state='checked'],
	&[data-state='mixed'] {
		border-color: var(--tile-checkbox-checked-border, #{$primary});
		background-color: var(--tile-checkbox-checked-background, #{$primary});
		color: var(--tile-checkbox-checked-color, #{$primary-foreground});
		box-shadow: var(--tile-checkbox-checked-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-checkbox-checked-focus-shadow, 0 0 0 1px #{$ring});
			outline: var(--tile-checkbox-checked-focus-outline, none);
			outline-offset: var(--tile-checkbox-checked-focus-offset, 0px);

			&[aria-invalid='true'] {
				box-shadow: var(--tile-checkbox-error-focus-shadow, 0 0 0 1px #{$destructive});
			}
		}
	}
}

.indicator {
	display: grid;
	place-content: center;
	color: currentColor;

	svg {
		width: var(--tile-checkbox-indicator-size, 0.875rem);
		height: var(--tile-checkbox-indicator-size, 0.875rem);
	}
}
